-- Frozen differential fixtures generated from real NumPy 2.3.5
local np=require("luaray_core")
assert(np._version=="0.109.0-dev")
local checks,cases=0,0
local function deep(a,b,desc)
    assert(type(a)==type(b),desc..': type mismatch: '..type(a)..' vs '..type(b))
    if type(a)=='table' then
        assert(#a==#b,desc..': length mismatch: '..#a..' vs '..#b)
        for i=1,#a do deep(a[i],b[i],desc..'['..i..']') end
    else
        assert(a==b,desc..': '..tostring(a)..' vs '..tostring(b))
    end
    checks=checks+1
end
do
local r=np.random.default_rng(4294967297)
local x=np.astype(np.arange(18,"int64"):reshape({3,2,3}),"int32")
local before=x:tolist()
local y=r:permuted(x,1,x)
deep(y.dtype,"int32","4294967297/(3, 2, 3)/int32/plain/0/out_same dtype")
deep(y:tolist(),{{{12,7,2},{15,4,17}},{{0,13,14},{9,16,5}},{{6,1,8},{3,10,11}}},"4294967297/(3, 2, 3)/int32/plain/0/out_same values")
deep(x:tolist(),{{{12,7,2},{15,4,17}},{{0,13,14},{9,16,5}},{{6,1,8},{3,10,11}}},"4294967297/(3, 2, 3)/int32/plain/0/out_same source")
assert(rawequal(y,x),"out must return identical ndarray")
deep(r:raw_hex(),"f3fe33f26b689233","4294967297/(3, 2, 3)/int32/plain/0/out_same pcg")
cases=cases+1; end
