local x=np.flip(np.astype(np.arange(8,"int64"):reshape({2,1,4}),"float32"),1)
local before=x:tolist()
local y=r:permuted(x,-1,x)
deep(y.dtype,"float32","4294967297/(2, 1, 4)/float32/flip/-1/out_same dtype")
deep(y:tolist(),{{{6.0,4.0,5.0,7.0}},{{1.0,2.0,0.0,3.0}}},"4294967297/(2, 1, 4)/float32/flip/-1/out_same values")
