local before=x:tolist()
local y=r:permuted(x,-1,x)
deep(y.dtype,"float32","4294967297/(1, 2, 4)/float32/transpose/-1/out_same dtype")
deep(y:tolist(),{{{0.0},{4.0}},{{1.0},{5.0}},{{2.0},{6.0}},{{3.0},{7.0}}},"4294967297/(1, 2, 4)/float32/transpose/-1/out_same values")
